@Configuration
public class GatewayRoutes {

    @Bean
    RouteLocator routes(RouteLocatorBuilder builder) {
        return builder.routes()
                .route("topic-service", r -> r
                        .path("/api/v1/topics/**")
                        .and().method(HttpMethod.GET, HttpMethod.POST)
                        .filters(f -> f
                                .stripPrefix(1)
                                .addRequestHeader("X-Gateway", "learnhub")
                                .circuitBreaker(c -> c.setName("topicCB")
                                        .setFallbackUri("forward:/fallback/topics")))
                        .uri("lb://topic-service"))
                .route("search-canary", r -> r
                        .path("/api/v1/search/**")
                        .and().header("X-Canary", "v2")
                        .filters(f -> f.stripPrefix(1))
                        .uri("lb://search-v2"))
                .build();
    }

    @Bean
    KeyResolver userKeyResolver() {
        return exchange -> exchange.getPrincipal()
                .map(Principal::getName)
                .defaultIfEmpty("anonymous");
    }
}

@Component
public class AuthGlobalFilter implements GlobalFilter, Ordered {
    private final JwtService jwtService;

    public AuthGlobalFilter(JwtService jwtService) {
        this.jwtService = jwtService;
    }

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        String path = exchange.getRequest().getURI().getPath();
        if (path.equals("/actuator/health") || path.startsWith("/api/v1/auth/")) {
            return chain.filter(exchange);
        }
        String authorization = exchange.getRequest().getHeaders()
                .getFirst(HttpHeaders.AUTHORIZATION);
        if (authorization == null || !authorization.startsWith("Bearer ")) {
            return unauthorized(exchange);
        }
        try {
            JwtUser user = jwtService.verify(authorization.substring(7));
            ServerHttpRequest request = exchange.getRequest().mutate()
                    .headers(headers -> {
                        headers.remove("X-User-Id");
                        headers.remove("X-User-Roles");
                    })
                    .header("X-User-Id", String.valueOf(user.id()))
                    .header("X-User-Roles", String.join(",", user.roles()))
                    .build();
            return chain.filter(exchange.mutate().request(request).build());
        } catch (JwtException ex) {
            return unauthorized(exchange);
        }
    }

    private Mono<Void> unauthorized(ServerWebExchange exchange) {
        exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
        return exchange.getResponse().setComplete();
    }

    @Override
    public int getOrder() {
        return -100;
    }
}
